def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [False] * (V + 1)
    dp[0] = True
    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    max_used = 0
    for cap in range(V, -1, -1):
        if dp[cap]:
            max_used = cap
            break
    return V - max_used

